                    "status": repo_obj.status[0],
                    "encoding": repo_obj.encoding,
                }
                for repo_obj in u.get_repo_objs(refresh=True)
            ],
        }

    @cherrypy.expose
    def index(self):
        return {
            "version": self.app.version,
        }

